// Mount a React island inside a legacy AngularJS directive
angular.module('legacy').directive('reactOrderSummary', () => ({
  scope: { orderId: '<' },
  link(scope, element) {
    const root = createRoot(element[0]);
    const render = () => root.render(<OrderSummary orderId={scope.orderId} />);
    scope.$watch('orderId', render);
    scope.$on('$destroy', () => root.unmount());
  },
}));

class FleetFeed {
  private seq = 0;
  constructor(private store: FleetStore, private socket: ReconnectingSocket) {
    socket.onOpen(async () => {
      const snapshot = await api.fleetSnapshot();
      store.replaceAll(snapshot.vehicles);
      this.seq = snapshot.seq;
    });
    socket.onMessage(msg => {
      if (msg.seq !== this.seq + 1) return socket.reconnect(); // gap → resync
      this.seq = msg.seq;
      store.queueUpdate(msg.vehicle); // batched per animation frame
    });
  }
}

