import DOMPurify from 'dompurify';

function SafeRichText({ html }: { html: string }) {
  const clean = useMemo(() => DOMPurify.sanitize(html, { USE_PROFILES: { html: true } }), [html]);
  return <div dangerouslySetInnerHTML={{ __html: clean }} />;
}

const SAFE_PROTOCOLS = new Set(['http:', 'https:', 'mailto:']);
function SafeLink({ href, children }: { href: string; children: ReactNode }) {
  const ok = (() => { try { return SAFE_PROTOCOLS.has(new URL(href, location.origin).protocol); } catch { return false; } })();
  return ok ? <a href={href} rel="noopener noreferrer">{children}</a> : <span>{children}</span>;
}

// Soak test (Playwright) to detect growth
test('memory stays bounded over repeated navigation', async ({ page }) => {
  await page.goto('/dashboard');
  const measure = () => page.evaluate(() => (performance as any).memory?.usedJSHeapSize ?? 0);
  const before = await measure();
  for (let i = 0; i < 200; i++) {
    await page.getByRole('link', { name: 'Reports' }).click();
    await page.getByRole('link', { name: 'Dashboard' }).click();
  }
  await page.evaluate(() => (window as any).gc?.()); // run Chromium with --js-flags=--expose-gc
  expect(await measure()).toBeLessThan(before * 1.5);
});
